  "cascade-templates": ".cascade-field {\n  max-inline-size: 18rem;\n}\n\n.cascade-option {\n  min-width: 0;\n  display: flex;\n  align-items: center;\n  gap: 0.625rem;\n}\n\n.cascade-option__mark {\n  width: 1.75rem;\n  height: 1.75rem;\n  display: grid;\n  place-items: center;\n  flex: 0 0 auto;\n  border-radius: 0.5rem;\n  background: var(--aeris-primary-soft);\n  color: var(--aeris-primary-text);\n  font-size: 0.6875rem;\n  font-weight: 800;\n}\n\n.cascade-option__copy {\n  min-width: 0;\n  display: grid;\n}\n\n.cascade-option__copy strong {\n  font-size: 0.875rem;\n}\n\n.cascade-option__copy small {\n  color: var(--aeris-text-2);\n  font-size: 0.75rem;\n}",
