  "chart-radial": ".chart-radial-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(min(100%, 12rem), 1fr));\n  gap: 1.5rem;\n}\n\n.chart-radial-grid section {\n  min-inline-size: 0;\n}\n\n.chart-radial-grid h4 {\n  margin-block: 0 1rem;\n  text-align: start;\n}\n\n.chart-radial-grid aeris-chart {\n  --aeris-chart-border: transparent;\n  --aeris-chart-padding: 0.5rem;\n  --aeris-chart-background: transparent;\n  inline-size: 100%;\n  max-inline-size: 14rem;\n  margin-inline: auto;\n}\n\n.chart-ring {\n  position: relative;\n  inline-size: 100%;\n  max-inline-size: 14rem;\n  margin-inline: auto;\n}\n\n.chart-ring-value {\n  position: absolute;\n  inset: 0;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 2rem;\n  font-weight: 700;\n  pointer-events: none;\n}\n\n.chart-ring-value span {\n  font-size: 1rem;\n  margin-inline-start: 0.125rem;\n}\n\n.chart-goals {\n  list-style: none;\n  padding: 0;\n  margin-block: 1rem 0;\n  display: grid;\n  gap: 0.5rem;\n}\n\n.chart-goals li {\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n}\n\n.chart-goals strong {\n  margin-inline-start: auto;\n}\n\n.chart-goal-dot {\n  inline-size: 0.5rem;\n  block-size: 0.5rem;\n  border-radius: 50%;\n  flex: 0 0 auto;\n}",
