  "class-names-conditional": ".class-names-demo {\n  display: grid;\n  gap: 1rem;\n}\n\n.class-names-actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.625rem;\n}\n\n.state-card {\n  padding: 1.25rem;\n  border: 1px solid var(--aeris-border);\n  border-radius: var(--aeris-radius-lg);\n  background: var(--aeris-surface);\n  transition: border-color 160ms ease, background 160ms ease, opacity 160ms ease;\n}\n\n.state-card--selected {\n  border-color: var(--aeris-primary);\n  background: var(--aeris-primary-soft);\n}\n\n.state-card--busy {\n  opacity: 0.55;\n}\n\n.state-card--emphasized {\n  box-shadow: inset 0 0 0 1px var(--aeris-border);\n}\n\n.class-names-demo {\n  display: grid;\n  gap: 1rem;\n}\n\n.class-names-actions,\n.framework-example {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.625rem;\n}\n\n.state-card {\n  padding: 1.25rem;\n  border: 1px solid var(--aeris-border);\n  border-radius: var(--aeris-radius-lg);\n  background: var(--aeris-surface);\n  transition: border-color 160ms ease, background 160ms ease, opacity 160ms ease;\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .state-card,\n    .composed-card--interactive {\n      transition: none;\n    }\n}",
